import React, { ChangeEvent, useId } from "react";
import clsx from "clsx";
import { Toggle as ToggleStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import useControlled from "../../lib/hooks/useControlled";
import { mockInputChangeEvent } from "../../lib/utils";
import { CommonProps } from "../helperTypes";

type Props = {
  /** If `true`, the component is checked */
  checked?: boolean;
  /** The default checked status for an uncontrolled component */
  defaultChecked?: boolean;
  /**
   * The id that will be passed to the underlying input element.
   */
  id?: string;  
  /** The label to show next to the `<input />` */
  label?: string;
  /** The callback for when the input's state changes */
  onChange?: (event: ChangeEvent<HTMLInputElement>, checked: boolean) => void;
  /**
   * The size of the toggle
   * @default medium
   */
  size?: "small" | "medium" | "large";
};

export type ToggleProps = Props & CommonProps;

const useStyles = createUseStyles(ToggleStyles, "toggle");

const Toggle = (props: ToggleProps) => {
  const {
    id: propsId,
    checked: checkedProp,
    defaultChecked,
    onChange,
    label,
    size,
    className,
    style,
    ...rest
  } = props;
  const defaultId = `toggle-${useId()}`;
  const inputEl = React.useRef(null);
  const classes = useStyles();
  const [checked, setCheckedState] = useControlled({
    value: checkedProp,
    defaultValue: defaultChecked,
  });

  const id = propsId || defaultId;
  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setCheckedState(e.target.checked);
    if (onChange) {
      onChange(e, e.target.checked);
    }
  };
  return (
    <div className={clsx(className, classes.root, size && classes[`_${size}`])} style={style}>
      <input
        className={classes.input}
        ref={inputEl}
        id={id}
        type="checkbox"
        checked={checked}
        onChange={handleChange}
        onKeyDown={(evt) => {
          if (evt.key !== "Enter") return;
          handleChange(mockInputChangeEvent(!checked, true));
        }}
        {...rest}
      />
      <label
        className={clsx(classes.label, { [classes.label_none]: !label })}
        htmlFor={id}
      >
        {label || <>&nbsp;</>}
      </label>
    </div>
  );
};

export default Toggle;
